import { useState, useEffect } from "react";
import axios from "axios";

function Dashboard() {
  const [data, setData] = useState({
    dealsClosed: 0,
    onlineVisitors: 0,
    onlineQueries: 0,
    properties: [],
    recentReviews: [],
    traffic: { socialMedia: 0, email: 0, thisMonth: 0 },
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        const res = await axios.get("http://localhost:5000/dashboard");
        setData(res.data);
      } catch (error) {
        console.error("Error fetching dashboard data:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchDashboardData();
  }, []);

  if (loading) return <div className="text-center text-white">Loading...</div>;

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <h1 className="text-3xl font-bold text-center mb-6 text-gray-800">
        Dashboard
      </h1>
      <div className="bg-white rounded-lg shadow-lg p-6">
        {/* Header Section */}
        <div className="flex justify-between items-center mb-6">
          <div className="text-gray-600">Zeng Wen</div>
          <button className="bg-blue-500 text-white px-4 py-2 rounded-lg">
            Create Listing
          </button>
        </div>

        {/* Main Dashboard */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {/* Welcome Card */}
          <div className="bg-pink-100 p-4 rounded-lg">
            <h2 className="text-lg font-semibold">
              Explore your new dashboard
            </h2>
            <p className="text-sm text-gray-600">
              Respond to guests, keep track of your reservations and earnings,
              and see how many travelers are looking at your listing!
            </p>
            <button className="mt-2 bg-blue-500 text-white px-3 py-1 rounded">
              See How It Works
            </button>
          </div>

          {/* Deals Closed */}
          <div className="bg-white p-4 rounded-lg shadow">
            <h3 className="text-md font-medium">Deals Closed</h3>
            <p className="text-2xl font-bold">{data.dealsClosed} This Year</p>
            {/* Add chart placeholder */}
          </div>

          {/* Online Visitors & Queries */}
          <div className="bg-white p-4 rounded-lg shadow">
            <h3 className="text-md font-medium">Online Visitors</h3>
            <p className="text-2xl font-bold">{data.onlineVisitors}</p>
          </div>
          <div className="bg-white p-4 rounded-lg shadow">
            <h3 className="text-md font-medium">Online Queries</h3>
            <p className="text-2xl font-bold">{data.onlineQueries}</p>
          </div>

          {/* Properties */}
          <div className="col-span-2 bg-white p-4 rounded-lg shadow">
            <h3 className="text-md font-medium">Properties</h3>
            <div className="grid grid-cols-2 gap-4">
              {data.properties > 0 &&
                Array.from({ length: Math.min(3, data.properties) }, (_, i) => (
                  <div key={i} className="bg-gray-100 p-2 rounded">
                    <img
                      src="http://localhost:5000/house_placeholder.jpg" // Replace with actual image
                      alt="Property"
                      className="w-full h-20 object-cover rounded"
                    />
                    <p className="text-sm">Property {i + 1}</p>
                    <p className="text-sm">$200/night</p>
                  </div>
                ))}
            </div>
          </div>

          {/* Traffic & Recent Reviews */}
          <div className="bg-white p-4 rounded-lg shadow">
            <h3 className="text-md font-medium">Traffic</h3>
            <div className="flex justify-between">
              <div>Social Media</div>
              <div>{data.traffic.socialMedia}%</div>
            </div>
            <div className="flex justify-between">
              <div>Email</div>
              <div>{data.traffic.email}%</div>
            </div>
            <div className="flex justify-between">
              <div>This Month</div>
              <div>{data.traffic.thisMonth}%</div>
            </div>
          </div>
          <div className="bg-white p-4 rounded-lg shadow">
            <h3 className="text-md font-medium">Recent Reviews</h3>
            {data.recentReviews.map((review, i) => (
              <p key={i} className="text-sm">
                {review.comment}
              </p>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
